package States_1StateDefinition {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Structure Context)
    state def TrafficLight {
       entry perform logStart;
       exit perform logEnd;
       state Red;
       state Green;
    }
}

package States_2Transitions {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Structure Context)
    transition t1
       first Red
       accept TimeEvent
       then Green;
}

package States_3GuardsEffects {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Structure Context)
    transition t2
       first Green
       if traffic == 0
       do action resetTimer
       then Red;
}

package States_4CompositeStates {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Structure Context)
    state Operational {
       entry ...
       state Normal;
       state Maintenance;
    }
}

package States_5ParallelStates {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Structure Context)
    state def System parallel {
       state Power {...}
       state Connectivity {...}
    }
}
